/**
 * Infill demo: ONE layer seen from above. The part's outline (two perimeter loops, the walls) is
 * drawn once; the infill inside it is generated by a function per pattern, from a density (percent)
 * and a layer number (so patterns that change from layer to layer visibly do).
 * Each generator returns an SVG path string; everything is clipped to the inside of the walls.
 * "Trace" draws the path in, like the nozzle following it.
 *
 * Density -> spacing: s = 400 / density (px), so 20% is a line every 20px and 100% is nearly solid.
 * The patterns are simplified 2D slices that show the idea, not the exact slicer output.
 */
import { gsap, prefersReducedMotion } from "../lib/reveal.js";
import { svgEl } from "../lib/svg.js";

const AREA = { x: 58, y: 38, w: 184, h: 164 }; // inside the inner wall
const CX = AREA.x + AREA.w / 2;
const CY = AREA.y + AREA.h / 2;
const REACH = 260; // lines are drawn longer than the area; the clip cuts them

const spacing = (d) => Math.max(4, 400 / Math.max(d, 4));
const f = (n) => n.toFixed(1);

/** Parallel lines at `angle` degrees, `s` apart, shifted by `offset`. */
function lines(angle, s, offset = 0) {
  const a = (angle * Math.PI) / 180;
  const dx = Math.cos(a);
  const dy = Math.sin(a);
  const nx = -dy;
  const ny = dx;
  let d = "";
  const n = Math.ceil(REACH / s);
  for (let k = -n; k <= n; k++) {
    const o = k * s + offset;
    const px = CX + nx * o;
    const py = CY + ny * o;
    d += `M${f(px - dx * REACH)} ${f(py - dy * REACH)}L${f(px + dx * REACH)} ${f(py + dy * REACH)}`;
  }
  return d;
}

/** Wavy line across the area (axis "x" = runs left-right) with phase `ph`. */
function wave(axis, pos, lam, amp, ph) {
  let d = "";
  for (let t = -20; t <= 220; t += 3) {
    const u = t / lam;
    const w = amp * Math.sin(2 * Math.PI * u + ph);
    const x = axis === "x" ? AREA.x - 10 + t * 1.1 : pos + w;
    const y = axis === "x" ? pos + w : AREA.y - 10 + t * 1.1;
    d += (d ? "L" : "M") + f(x) + " " + f(y);
  }
  return d;
}

function hexagons(r) {
  const w = Math.sqrt(3) * r;
  let d = "";
  for (let row = -1; row * 1.5 * r < AREA.h + 2 * r; row++) {
    for (let col = -1; col * w < AREA.w + 2 * w; col++) {
      const cx = AREA.x + col * w + (row % 2 ? w / 2 : 0);
      const cy = AREA.y + row * 1.5 * r;
      for (let i = 0; i < 6; i++) {
        const a1 = (Math.PI / 180) * (60 * i - 30);
        const a2 = (Math.PI / 180) * (60 * (i + 1) - 30);
        d += `M${f(cx + r * Math.cos(a1))} ${f(cy + r * Math.sin(a1))}L${f(cx + r * Math.cos(a2))} ${f(cy + r * Math.sin(a2))}`;
      }
    }
  }
  return d;
}

function concentric(s) {
  let d = "";
  for (let inset = 0; inset < Math.min(AREA.w, AREA.h) / 2; inset += s) {
    const x = AREA.x + inset;
    const y = AREA.y + inset;
    const w = AREA.w - 2 * inset;
    const h = AREA.h - 2 * inset;
    if (w < 2 || h < 2) break;
    d += `M${f(x)} ${f(y)}h${f(w)}v${f(h)}h${f(-w)}Z`;
  }
  return d;
}

/** A few sparse branching lines that only reach up under the top surface (a "lightning" tree). */
function lightning(layer, d) {
  const n = 2 + Math.round(d / 17); // 2 trunks at 5% ... 8 at 100%: the slider visibly adds branches
  let out = "";
  for (let i = 0; i < n; i++) {
    const x0 = AREA.x + ((i + 0.5) * AREA.w) / n;
    const sway = ((layer % 3) - 1) * 6;
    out += `M${f(x0)} ${AREA.y + AREA.h}L${f(x0 + sway)} ${f(CY + 20)}L${f(x0 + sway - 22)} ${f(CY - 30)}M${f(x0 + sway)} ${f(CY + 20)}L${f(x0 + sway + 22)} ${f(CY - 34)}`;
  }
  return out;
}

/** Pattern id -> path generator (density in %, layer number). Keys match data/infill.js ids. */
export const generators = {
  lines: (d, l) => lines(l % 2 ? -45 : 45, spacing(d)),
  grid: (d, l) => lines(45, spacing(d) * 2) + lines(-45, spacing(d) * 2),
  triangles: (d, l) => lines(0, spacing(d) * 3) + lines(60, spacing(d) * 3) + lines(120, spacing(d) * 3),
  cubic: (d, l) => {
    const s = spacing(d) * 3;
    return lines(0, s, (l * s) / 3) + lines(60, s, (l * s) / 3) + lines(120, s, (l * s) / 3);
  },
  gyroid: (d, l) => {
    const s = spacing(d) * 2;
    const lam = s * 2;
    const ph = (l % 6) * (Math.PI / 3);
    let out = "";
    for (let p = AREA.y - s; p < AREA.y + AREA.h + s; p += s) out += wave("x", p, lam, s * 0.4, ph);
    for (let p = AREA.x - s; p < AREA.x + AREA.w + s; p += s) out += wave("y", p, lam, s * 0.4, ph + Math.PI / 2);
    return out;
  },
  honeycomb: (d) => hexagons(Math.max(7, spacing(d) * 0.9)),
  concentric: (d) => concentric(spacing(d)),
  lightning: (d, l) => lightning(l, d),
};

/**
 * @param {SVGElement} svg
 * @returns {{set(pattern:string, density:number, layer:number, opts?:{trace?:boolean}):void}}
 */
export function createInfill(svg) {
  svg.setAttribute("viewBox", "0 0 300 240");
  svg.setAttribute("role", "img");

  const clip = svgEl("clipPath", { id: "infill-clip" }, svgEl("rect", { x: AREA.x, y: AREA.y, width: AREA.w, height: AREA.h }));
  const outer = svgEl("rect", { class: "d-fixed", x: 40, y: 20, width: 220, height: 200, rx: 12 }); // outer wall
  const inner = svgEl("rect", { class: "d-fixed", x: 50, y: 30, width: 200, height: 180, rx: 8 }); // second wall
  const path = svgEl("path", { class: "infill-path", pathLength: 1 });
  const group = svgEl("g", { "clip-path": "url(#infill-clip)" }, path);
  svg.append(svgEl("defs", {}, clip), group, outer, inner);

  let tween = null;
  function set(pattern, density, layer, { trace = true } = {}) {
    path.setAttribute("d", generators[pattern](density, layer));
    svg.setAttribute("aria-label", `מבט מלמעלה על שכבה אחת: מילוי ${pattern} בצפיפות ${density} אחוז`);
    tween?.kill();
    if (!trace || prefersReducedMotion()) {
      gsap.set(path, { strokeDasharray: "none", strokeDashoffset: 0 });
      return;
    }
    // trace: draw the path in as if the nozzle follows it
    gsap.set(path, { strokeDasharray: 1, strokeDashoffset: 1 });
    tween = gsap.to(path, { strokeDashoffset: 0, duration: 1.3, ease: "power1.inOut", onComplete: () => gsap.set(path, { strokeDasharray: "none" }) });
  }
  return { set };
}
